    private static GrowthQuestionSpec Q(string id, string family, string query, string need,
        GrowthFact[] targets, GrowthFact support, UsefulRelation[] firstTargetSupports,
        UsefulRelation[] supportAlsoSupports) =>
        new(id, family, query, need, targets, support,
            targets.Select((_, facet) => facet == 0 ? firstTargetSupports : AdditionalFacetSupport(id, facet)).ToArray(),
            supportAlsoSupports);

    // Explicit additional-facet adjudication: never inherit the first facet's labels.
    private static UsefulRelation[] AdditionalFacetSupport(string question, int facet) => (question, facet) switch
    {
        ("q01", 1) => [L("q02", "Transaction lifetime supplies release-timing evidence for a bounded retry.")],
        ("q07", 1) => [L("q15", "The explicit existing-destination collision rule also constrains extraction.")],
        ("q10", 1) => [L("q34", "Generation mismatch invalidates the endpoint rather than accepting the existing process.")],
        ("q13", 1) => [L("q08", "The extraction-specific budget facet supplies final-path and component limits.")],
        ("q19", 1) => [L("q23", "Late cancellation cannot erase a committed effect, so replay still needs reconciliation.")],
        ("q24", 1) => [L("q19", "The after-commitment facet preserves the committed effect in reporting.")],
        ("q36", 1) => [L("q06", "Path replacement explains why physical custody cannot rely on a directory name alone.")],
        ("q44", 1) => [L("q48", "The selection facet explicitly denies expansion of external authority.")],
        _ => []
    };
    private static GrowthFact F(string title, string content, params string[] tags) => new(title, content, tags);
    private static UsefulRelation L(string questionId, string rationale) => new(questionId, rationale);
